import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MotionProps } from '@primereact/types/primitive/motion';
/**
 * Defines passthrough(pt) options type in SidebarBackdrop component.
 */
export type SidebarBackdropPassThroughType<E> = PassThroughType<SidebarBackdropInstance, E>;
/**
 * Defines passthrough(pt) options of SidebarBackdrop component.
 */
export interface SidebarBackdropPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SidebarBackdropPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in SidebarBackdrop component.
 */
export interface SidebarBackdropProps extends BaseComponentProps<SidebarBackdropInstance, unknown, SidebarBackdropPassThrough> {
    /**
     * The motion properties for the backdrop animation.
     */
    motionProps?: MotionProps | undefined;
}
/**
 * Defines valid state in SidebarBackdrop component.
 */
export interface SidebarBackdropState {
}
/**
 * Defines the methods and properties exposed by SidebarBackdrop component.
 */
export interface SidebarBackdropExposes {
}
/**
 * Instance of SidebarBackdrop component.
 */
export type SidebarBackdropInstance = ComponentInstance<SidebarBackdropProps, SidebarBackdropState, SidebarBackdropExposes>;
